        req = urllib.request.Request(url, data=request_data, headers=self._headers, method=method)
        for attempt in range(self._max_retries + 1):
            try:
                with urllib.request.urlopen(req, timeout=self._timeout) as response:
                    if response.getcode() == 204:
                        return {}
                    response_data = response.read().decode("utf-8")
                    try:
                        return json.loads(response_data)
                    except json.JSONDecodeError:
                        logger.warning(f"Non-JSON response: {response_data[:100]}")
                        return {}
            except urllib.error.HTTPError as e:
                if 500 <= e.code < 600 and attempt < self._max_retries:
                    wait = 2 ** attempt
                    logger.warning(f"Retry {attempt + 1}/{self._max_retries} after {wait}s: {e.code}")
                    time.sleep(wait)
                    continue
                error_msg = e.read().decode("utf-8") if hasattr(e, 'read') and e.code != 204 else ""
                raise RampSDKError(f"API request failed: {e.code} - {error_msg}")
