                if attempt < self._max_retries:
                    wait = 2 ** attempt
                    logger.warning(f"Retry {attempt + 1}/{self._max_retries} after {wait}s: {str(e)}")
                    time.sleep(wait)
                    continue
                raise RampSDKError(f"Request error: {str(e)}")
        raise RampSDKError("Max retries exceeded")

