            raise RampSDKError("Invalid response from API: missing session_id")
        status = self._normalize_status(response.get("status", "pending"))
        return PaymentSession(
            session_id=response["session_id"],
            amount=amount,
            fiat_currency=fiat_currency,
            settlement_currency=settlement_currency,
            wallet_address=wallet_address,
            status=status
        )

    def process_apple_pay(
        self,
        session: PaymentSession,
        apple_pay_token: str,
        merchant_identifier: str
    ) -> Dict[str, Any]:
        if not apple_pay_token:
            raise ValueError("Apple Pay token cannot be empty")
        if not merchant_identifier:
            raise ValueError("Merchant identifier cannot be empty")
        token_hash = hashlib.sha256(apple_pay_token.encode()).hexdigest()
        payload = {
            "session_id": session.session_id,
            "payment_token": apple_pay_token,
            "merchant_identifier": merchant_identifier,
            "token_hash": token_hash
        }
        response = self._make_request("POST", f"/sessions/{session.session_id}/apple-pay", payload)
        session.status = self._normalize_status(response.get("status", "pending"))
        session.payment_token = apple_pay_token
        transaction_id = response.get("transaction_id")
        if transaction_id:
            self._settle_instantly(session, transaction_id)
        else:
            logger.warning(f"No transaction_id in response for session {session.session_id}")
        return response

    def _settle_instantly(self, session: PaymentSession, transaction_id: Optional[str] = None):
        tx_id = transaction_id
        if not tx_id:
            status_response = self._make_request("GET", f"/sessions/{session.session_id}")
            tx_id = status_response.get("transaction_id")
            if not tx_id:
                raise RampSDKError(f"No transaction_id found for session {session.session_id}")
        settle_payload = {
            "transaction_id": tx_id,
            "settle_immediately": True
        }
        self._make_request("POST", f"/transactions/{tx_id}/settle", settle_payload)
        logger.info(f"Instant settlement triggered for transaction {tx_id}")

    def get_session_status(self, session_id: str) -> PaymentSession:
        if not session_id:
            raise ValueError("Session ID cannot be empty")
        response = self._make_request("GET", f"/sessions/{session_id}")
        amount = float(response.get("amount", 0.0) or 0.0)
        fiat_currency = str(response.get("fiat_currency", "") or "")
        wallet_address = str(response.get("wallet_address", "") or "")
        status = self._normalize_status(response.get("status", "pending"))
        settlement_currency = self._normalize_settlement_currency(response.get("settlement_currency", "BTC"))
        return PaymentSession(
            session_id=session_id,
            amount=amount,
            fiat_currency=fiat_currency,
            settlement_currency=settlement_currency,
            wallet_address=wallet_address,
            status=status
        )

    def list_recent_sessions(self, limit: int = 10) -> list[PaymentSession]:
        if not isinstance(limit, int) or limit < 1 or limit > 100:
            raise ValueError("Limit must be between 1 and 100")
        response = self._make_request("GET", f"/sessions?limit={limit}")
        sessions: list[PaymentSession] = []
        for sess_data in response.get("sessions", []):
            amount = float(sess_data.get("amount", 0.0) or 0.0)
            fiat_currency = str(sess_data.get("fiat_currency", "") or "")
            wallet_address = str(sess_data.get("wallet_address", "") or "")
            status = self._normalize_status(sess_data.get("status", "pending"))
            settlement_currency = self._normalize_settlement_currency(sess_data.get("settlement_currency", "BTC"))
            session_id = str(sess_data.get("session_id", "") or "")
            if session_id:
                sessions.append(PaymentSession(
                    session_id=session_id,
                    amount=amount,
                    fiat_currency=fiat_currency,
                    settlement_currency=settlement_currency,
                    wallet_address=wallet_address,
                    status=status
                ))
        return sessions
